(async () => {
  const pc = await import('/node_modules/.vite/deps/playcanvas.js').catch(() => import('/@id/playcanvas'));
  const { buildCircuit, clearMaterialCache } = await import('/src/game/scene.js');
  const { makeTrackPath } = await import('/src/game/trackPath.js');
  const { CALENDAR, GRID_TEAMS } = await import('/src/data/season.js');
  const out = [];
  for (const t of CALENDAR) {
    const canvas = document.createElement('canvas');
    const app = new pc.Application(canvas, {});
    const path = makeTrackPath(t.points);
    const root = buildCircuit(app, path, { teams: GRID_TEAMS, env: t.env, seed: t.id.length * 7 + 3, pitSide: t.pitSide });
    const a = root.placement.audit();
    out.push({ id: t.id, ...a, height: Math.max(...path.points.map((p) => p.y)), verts: root.findByName('static-scenery').render.meshInstances[0].mesh.vertexBuffer.numVertices });
    const device = app.graphicsDevice;
    app.destroy();
    clearMaterialCache(device);
  }
  const bad = out.filter((o) => o.overlaps || o.onRoad);
  return JSON.stringify({ ok: bad.length === 0, circuits: out.length, bad, summary: out.map((o) => `${o.id}: ${o.placed} placed, ${o.refused} refused${o.height > 1 ? ', bridge' : ''}, ${Math.round(o.verts / 1000)}k verts`) });
})().then((r) => { const j = JSON.parse(r); if (!j.ok) throw new Error('overlapping scenery: ' + JSON.stringify(j.bad)); return r; })
